Extrait:
using (var saveFileDialog = new SaveFileDialog())              {                  saveFileDialog.DefaultExt = ".txt";                  if (saveFileDialog.ShowDialog() == DialogResult.OK)                  {                      File.WriteAllLines(saveFileDialog.FileName,                          ListOfTexts.Select(msg =>                          $"%%% MESSAGE : {msg.ID:X3} | {Constants.textsLocations[msg.ID]} %%% 
{AddNewLinesToCommands(msg.ContentsParsed)}

"));                  }              }

